import {emptyState,purge} from './core.mjs';
const DB='wonangfee-v1';const CHANNEL='wonangfee-state';
let db;let broadcast;
export async function initStore(onExternal){db=await new Promise((resolve,reject)=>{const q=indexedDB.open(DB,1);q.onupgradeneeded=()=>q.result.createObjectStore('state');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error||Error('无法打开浏览器存储'));q.onblocked=()=>reject(Error('请关闭旧标签页后重试'));});if(globalThis.BroadcastChannel){broadcast=new BroadcastChannel(CHANNEL);broadcast.onmessage=()=>onExternal?.();}return readState();}
export function readState(){return new Promise((resolve,reject)=>{const tx=db.transaction('state','readonly');const q=tx.objectStore('state').get('main');q.onsuccess=()=>resolve(purge(q.result||emptyState()));q.onerror=()=>reject(q.error);});}
export function writeState(expected,change){return new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');const store=tx.objectStore('state');const req=store.get('main');let next,result,custom;req.onsuccess=()=>{try{next=purge(req.result||emptyState());if(next.schema!==1)throw Error('此数据版本无法读取，请先备份');if(next.revision!==expected)throw Error('另一个页面更新了数据，请关闭表单后重试');result=change(next);next.revision++;next.savedAt=new Date().toISOString();store.put(next,'main');}catch(e){custom=e;tx.abort();}};tx.oncomplete=()=>{broadcast?.postMessage('changed');resolve({state:next,result});};tx.onerror=()=>reject(custom||tx.error||Error('保存失败，请检查设备空间'));tx.onabort=()=>reject(custom||tx.error||Error('保存失败，输入已保留'));});}
